dual_motor_duration.source:
Blockly.Blocks['dual_motor_duration'] = {

  init: function() 

  {

    var dropdown_1 = new Blockly.FieldDropdown(GetPortAToDList());

    var dropdown_2 = new Blockly.FieldDropdown(GetPortAToDList());

    this.appendDummyInput()

        .setAlign(Blockly.ALIGN_CENTRE)

        .appendField(new Blockly.FieldImage("pic\\block_icon\\motor.png", 24, 24, "*"))

        .appendField(Blockly.Msg.ABILIX_SCRATCH_MOTOR)

        .appendField( dropdown_1,"port_1");

    this.appendValueInput("speed_1")

        .setCheck("Number")

        .setAlign(Blockly.ALIGN_RIGHT)

        .appendField(Blockly.Msg.ABILIX_SCRATCH_SPEED);

    this.appendDummyInput()

        .appendField("%");

    this.appendDummyInput()

        .appendField(",");

    this.appendDummyInput()

         .setAlign(Blockly.ALIGN_CENTRE)        

        .appendField(Blockly.Msg.ABILIX_SCRATCH_MOTOR)

        .appendField(dropdown_2, "port_2");

    this.appendValueInput("speed_2")

        .setCheck("Number")

        .setAlign(Blockly.ALIGN_RIGHT)

        .appendField(Blockly.Msg.ABILIX_SCRATCH_SPEED);

    this.appendDummyInput()

        .appendField("%");

    this.appendDummyInput()

        .appendField(",")

    this.appendValueInput("time")

        .setCheck("Number")

        .setAlign(Blockly.ALIGN_RIGHT)

        .appendField(Blockly.Msg.ABILIX_SCRATCH_CONTINUE); // c

    this.appendDummyInput()

        .setAlign(Blockly.ALIGN_CENTRE)  

        .appendField(Blockly.Msg.ABILIX_SCRATCH_SECOND);

    this.setInputsInline(true);

    this.setPreviousStatement(true, null);

    this.setNextStatement(true, null);

    this.setColour(BLOCK_RUN_HUE);

    this.setTooltip("");

    this.setHelpUrl("");



     this.setOnChange( function(changeEvent ){



      // var indexPort1 = this.getFieldValue('port_1');

      // var indexPort2 = this.getFieldValue('port_2');

      if( changeEvent instanceof Blockly.Events.Change){

        // this.setWarningText( "Blockly.Events.Change" );   //typeof(changeEvent)

        if(changeEvent.name == "port_1"){

            if( changeEvent.newValue == this.getFieldValue('port_2')){

                dropdown_1.setValue(changeEvent.oldValue);

            }

        }

        else if(changeEvent.name == "port_2"){

            if( changeEvent.newValue == this.getFieldValue('port_1')){

                dropdown_2.setValue(changeEvent.oldValue);

            }

        }

      }





      // if(indexPort1 != indexPort2 )

      // {

      //   // port3Dropdown.setValue( Blockly.Msg.ABILIX_SCRATCH_PORT.replace("%1", PortEnStringMap[indexPort1]) );

      //   port3Dropdown.menuGenerator_ = [ [Blockly.Msg.ABILIX_SCRATCH_PORT.replace("%1", PortEnStringMap[indexPort1]), indexPort1], [Blockly.Msg.ABILIX_SCRATCH_PORT.replace("%1", PortEnStringMap[indexPort2]), indexPort2]];

      // }

      // else{

      //   // port3Dropdown.setValue( Blockly.Msg.ABILIX_SCRATCH_PORT.replace("%1", PortEnStringMap[indexPort1]) );

      //   port3Dropdown.menuGenerator_ = [ [Blockly.Msg.ABILIX_SCRATCH_PORT.replace("%1", PortEnStringMap[indexPort1]), indexPort1]];

      // }



      // }



    });

  }

}

dual_motor_angle.source:
Blockly.Blocks['dual_motor_angle'] = {

  init: function() 

  {   

//[  [Blockly.Msg.ABILIX_SCRATCH_PORT.replace("%1", "A"), "1"], [Blockly.Msg.ABILIX_SCRATCH_PORT.replace("%1", "B"), "2"] ]

    var port3Dropdown = new Blockly.FieldDropdown(GetPortAToDList());



    this.appendDummyInput()

        .setAlign(Blockly.ALIGN_CENTRE)

        .appendField(new Blockly.FieldImage("pic\\block_icon\\motor.png", 24, 24, "*"))

        .appendField(Blockly.Msg.ABILIX_SCRATCH_MOTOR)

        .appendField(new Blockly.FieldDropdown(GetPortAToDList()), "port_1");

    this.appendValueInput("speed_1")

        .setCheck("Number")

        .setAlign(Blockly.ALIGN_RIGHT)

        .appendField(Blockly.Msg.ABILIX_SCRATCH_SPEED);

    this.appendDummyInput()

        .appendField("%");

    this.appendDummyInput()

        .appendField(",");

    this.appendDummyInput()

         .setAlign(Blockly.ALIGN_CENTRE)        

        .appendField(Blockly.Msg.ABILIX_SCRATCH_MOTOR)

        .appendField(new Blockly.FieldDropdown(GetPortAToDList()), "port_2");

    this.appendValueInput("speed_2")

        .setCheck("Number")

        .setAlign(Blockly.ALIGN_RIGHT)

        .appendField(Blockly.Msg.ABILIX_SCRATCH_SPEED);

    this.appendDummyInput()

        .appendField("%");

    this.appendDummyInput()

        .appendField(",")

    //port_3: which port group needs to be stopped

     this.appendDummyInput()

        .appendField( Blockly.Msg.ABILIX_SCRATCH_Until + Blockly.Msg.ABILIX_SCRATCH_MOTOR )

        // [  [Blockly.Msg.ABILIX_SCRATCH_PORT.replace("%1", "A"), "1"], [Blockly.Msg.ABILIX_SCRATCH_PORT.replace("%1", "B"), "2"] ]

        .appendField(port3Dropdown, "port_3");

    this.appendDummyInput()

        .appendField(Blockly.Msg.ABILIX_SCRATCH_CoderGreaterThan);

    this.appendValueInput("angle")

        .setCheck("Number")

        .setAlign(Blockly.ALIGN_RIGHT);

    this.appendDummyInput()

        .appendField(Blockly.Msg.ABILIX_SCRATCH_STOP);

    this.setInputsInline(true);

    this.setPreviousStatement(true, null);

    this.setNextStatement(true, null);

    this.setColour(BLOCK_RUN_HUE);

    this.setTooltip("");

    this.setHelpUrl("");



    var setDropdown = function(indexPort1,indexPort2)

    {



      if(indexPort1 != indexPort2 )

      {

        // this.setWarningText( '!=OnChange: ' + indexPort1 + ',' +  indexPort2); 



        // port3Dropdown.menuGenerator_ = [ [Blockly.Msg.ABILIX_SCRATCH_PORT.replace("%1", PortEnStringMap[indexPort1]), indexPort1], [Blockly.Msg.ABILIX_SCRATCH_PORT.replace("%1", PortEnStringMap[indexPort2]), indexPort2]];

        port3Dropdown.ResetMenu([ [Blockly.Msg.ABILIX_SCRATCH_PORT.replace("%1", PortEnStringMap[indexPort1]), indexPort1], [Blockly.Msg.ABILIX_SCRATCH_PORT.replace("%1", PortEnStringMap[indexPort2]), indexPort2]]);

        // port3Dropdown.showEditor_();            

        // var ary = [ [Blockly.Msg.ABILIX_SCRATCH_PORT.replace("%1", PortEnStringMap[indexPort1]), indexPort1], 

        //             [Blockly.Msg.ABILIX_SCRATCH_PORT.replace("%1", PortEnStringMap[indexPort2]), indexPort2]];

        // port3Dropdown= new Blockly.FieldDropdown(ary);

      }

      else{

        // this.setWarningText( '==OnChange: ' + indexPort1 + ',' +  indexPort2); 

        // port3Dropdown.menuGenerator_ = [ [Blockly.Msg.ABILIX_SCRATCH_PORT.replace("%1", PortEnStringMap[indexPort1]), indexPort1]];

        port3Dropdown.ResetMenu([ [Blockly.Msg.ABILIX_SCRATCH_PORT.replace("%1", PortEnStringMap[indexPort1]), indexPort1] ]);

        // port3Dropdown.setValue( Blockly.Msg.ABILIX_SCRATCH_PORT.replace("%1", PortEnStringMap[indexPort1]) );

      }

    };





    this.setOnChange( function(changeEvent )

    {

        var indexPort1 = this.getFieldValue('port_1');

        var indexPort2 = this.getFieldValue('port_2');

        if( changeEvent instanceof Blockly.Events.Create)

        {         

           setDropdown(indexPort1,indexPort2);

        }

          // this.setWarningText(this.getFieldValue('port_1')  );

          else if( changeEvent instanceof Blockly.Events.Change  && ( changeEvent.name == "port_1" || changeEvent.name == "port_2"))

          {

             setDropdown(indexPort1,indexPort2);

          } 



    });



  }



}

