set_smart_light.source:
Blockly.Blocks['set_smart_light'] = {

    init: function() {

    var modeField = new Blockly.FieldDropdown([[Blockly.Msg["ABILIX_SCRATCH_LIGHT_ON"], "1"], 

                                               [Blockly.Msg["ABILIX_SCRATCH_LIGHT_FLASH"], "2"], 

                                               [Blockly.Msg["ABILIX_SCRATCH_LIGHT_BREATH"], "3"]]);

    var periodTitleField = new Blockly.FieldLabel(Blockly.Msg["ABILIX_SCRATCH_CYCLE"]);

    var periodField = new Blockly.FieldNumber(3);

    var secondTitleField = new Blockly.FieldLabel(Blockly.Msg["ABILIX_SCRATCH_SECOND"]);

    var colourField = new Blockly.FieldColour("#FF0000");

    colourField.setColours(new Array("#FFFFFF", "#FDFE1E", "#810FFD", "#00FEFE", "#7DFE1E", "#FE7F09", "#FE11FD", "#0F80FD", "#00FE1E", "#FE0303", "#FE0676", "#130FFD"), null);

    colourField.setColumns(4);



    periodTitleField.setVisible(false);

    periodField.setVisible(false);

    secondTitleField.setVisible(false);



    var validateMode = function (modeString)

    {

        if (modeString == '1')

        {

            periodTitleField.setVisible(false);

            periodField.setVisible(false);

            secondTitleField.setVisible(false);

        }

        else if (modeString == '2')

        {

            periodTitleField.setVisible(true);

            periodField.setVisible(true);

            secondTitleField.setVisible(true);

        }

        else if (modeString == '3')

        {

            periodTitleField.setVisible(true);

            periodField.setVisible(true);

            secondTitleField.setVisible(true);

        }

    }



    var validatePeriod = function (periodString)

    {

        var period = parseInt(periodString);

        if (period < 0)

            period = 0

        else if (period > 10)

            period = 10

        return period.toString();

    }



    modeField.setValidator(validateMode);

    periodField.setValidator(validatePeriod);

    this.appendDummyInput()

        .appendField(new Blockly.FieldImage("pic/block_icon/intelligent_light.png", 24, 24, "*"))

        .appendField(Blockly.Msg["ABILIX_SCRATCH_SMARTLIGHT"])

        .appendField(new Blockly.FieldDropdown(GetPort1To12List()), "port")

        .appendField(Blockly.Msg["COLOUR_RGB_TITLE"])

        .appendField(colourField, "colour")

        .appendField(Blockly.Msg["ABILIX_SCRATCH_MODE"])

        .appendField(modeField, "mode")

        .appendField(periodTitleField, "period_title")

        .appendField(periodField, "period")

        .appendField(secondTitleField, "second_title");

    this.setInputsInline(true);

    this.setPreviousStatement(true, null);

    this.setNextStatement(true, null);

    this.setColour(BLOCK_SOUND_AND_LIGHT_HUE);

    this.setTooltip('');

    this.setHelpUrl('http://www.example.com/');



    validateMode(this.getFieldValue('mode'));

    validatePeriod(this.getFieldValue('period'));

    }

}

