Blockly.Blocks['text_replace'] = {
  /**
   * Block for replacing one string with another in the text.
   * @this Blockly.Block
   */
  init: function() {
    this.jsonInit({
      "message0": Blockly.Msg['TEXT_REPLACE_MESSAGE0'],
